def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_F(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in range(1, 6):
    S_N = calculate_S(N)
    F_N = calculate_F(N)
    results[N] = {
        "S(N)": S_N,
        "F(N)": F_N,
        "Match": S_N == F_N
    }

print("Results for N=1 to 5:")
for N, data in results.items():
    print(f"N={N}: S(N) = {data['S(N)']}, F(N) = {data['F(N)']}, Match = {data['Match']}")
